# -*- coding: utf-8 -*-
"""CUT Improvement Auto / Approved layout finishing touches.

Only updates frontend React SOURCE, never built releases, backend or data.
Safe to run after the approved design installer, with or without Night refinement.
Place in PROJECT/scripts and run with the project's Python interpreter.
"""
from __future__ import annotations
import base64, hashlib, os, shutil, sys, tempfile, zlib
from datetime import datetime
from pathlib import Path

RECORDS = {'frontend/src/App.tsx': {'old': 'b0d4602e1ae89d518cb5605a57a43f49dfee978ebbbdd71e4c09d29192fffd9a', 'new': '9e783a4077bc58ed137ac009b0bed693d26ff362382b5276cdf98bd131ebeac7', 'blob': ''}, 'frontend/src/styles/cut-design-final-touches.css': {'old': None, 'new': 'f2c9fbd4315a8fd7ad7747df2bfbc04416ea2591c9f32b020eaa3173b60da655', 'blob': ''}, 'frontend/public/cut-night-assets/approved-light-hero.jpg': {'old': None, 'new': '16c780d825bd15d5edaf419818907d778e2e7716dc925dcaf0b0538e2793b56b', 'blob': ''}}
ALLOWED_LAYOUT_SHA256 = {
    'b80124331f220747fa01ce2a0db7dcd15d61d1f261d4ef04a1459497e1a3ae9a',
    '436f456169fb33fab96ba07273f4e43710cc466d10cc80f3698d1812cd6c441f',
}
COMPANY_LOGO_SHA256 = '5cd04ae9ab8de71eb6f7cb17de8b19feebc4355619a1e935e43f54ecc9eb9075'


def sha(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,temp=tempfile.mkstemp(prefix='.cut-final-design-',suffix='.tmp',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temp,path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def main() -> int:
    print('=== CUT Improvement Auto / Final Design Touches ===')
    script=Path(__file__).resolve()
    root=script.parent.parent
    if script.parent.name.lower()!='scripts' or not (root/'backend/app/main.py').is_file():
        raise RuntimeError('Place this installer in PROJECT/scripts. No files changed.')
    layout=root/'frontend/src/styles/cut-dashboard-layout.css'
    logo=root/'frontend/public/cut-night-assets/improvement-auto-logo.png'
    theme=root/'frontend/src/components/CutThemeControl.tsx'
    if not layout.is_file() or sha(layout.read_bytes()) not in ALLOWED_LAYOUT_SHA256:
        raise RuntimeError('Approved layout CSS is missing or has custom edits. No files changed.')
    if not logo.is_file() or sha(logo.read_bytes())!=COMPANY_LOGO_SHA256:
        raise RuntimeError('Approved company logo missing/changed. No files changed.')
    if not theme.is_file():
        raise RuntimeError('Theme switcher is missing. No files changed.')

    actions={}
    for rel,rec in RECORDS.items():
        target=root/rel
        data=zlib.decompress(base64.b64decode(rec['blob']))
        if sha(data)!=rec['new']:
            raise RuntimeError('Embedded installer data corrupt: '+rel)
        existing=target.read_bytes() if target.is_file() else None
        if existing is not None and sha(existing)==rec['new']:
            continue
        if rec['old'] is None:
            if existing is not None:
                raise RuntimeError('Refusing to overwrite existing custom file: '+rel)
        elif existing is None or sha(existing)!=rec['old']:
            raise RuntimeError('App.tsx differs from the approved snapshot. Nothing changed. Please send the current file.')
        actions[target]=data

    if not actions:
        print('OK: final touches already installed; no changes needed.')
        return 0

    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup=root.parent/'CUT_Improvement_Auto_DevArchive'/'final_design_backups'/stamp
    backup.mkdir(parents=True,exist_ok=False)
    original={p:p.read_bytes() if p.is_file() else None for p in actions}
    for path,data in original.items():
        if data is not None:
            dest=backup/path.relative_to(root)
            dest.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(path,dest)
            if sha(dest.read_bytes())!=sha(data):
                raise RuntimeError('Backup validation failed; no files changed.')

    # Write CSS and image first; activate them by importing from App.tsx last.
    paths=sorted(actions,key=lambda p:p.name=='App.tsx')
    written=[]
    try:
        for path in paths:
            atomic_write(path,actions[path])
            written.append(path)
            if sha(path.read_bytes())!=sha(actions[path]):
                raise RuntimeError('Write verification failed: '+str(path))
    except BaseException:
        for path in reversed(written):
            before=original[path]
            if before is None: path.unlink(missing_ok=True)
            else: atomic_write(path,before)
        print('ERROR: changes reverted. Backup: '+str(backup),file=sys.stderr)
        raise

    print('OK: masthead compact in both themes.')
    print('OK: duplicate logo and company name removed from sidebar; main header retained.')
    print('OK: light automotive banner installed.')
    print('OK: dark navy accent stripes added to light theme.')
    print('OK: existing theme selector and real dashboard data unchanged.')
    print('BACKUP:',backup)
    print('CHANGED:',', '.join(str(p.relative_to(root)) for p in paths))
    print('UNTOUCHED: dist, active release 0.1.0, backend, DB, MAX, photos, .env, backups, Git.')
    print('NEXT: check Vite preview at http://127.0.0.1:5173/ (do not build or activate yet).')
    return 0

if __name__=='__main__':
    try:
        raise SystemExit(main())
    except Exception as exc:
        print('INSTALL FAILED:',str(exc),file=sys.stderr)
        raise SystemExit(1)
